!function(){const e=document.createElement("link").relList;if(!(e&&e.supports&&e.supports("modulepreload"))){for(const e of document.querySelectorAll('link[rel="modulepreload"]'))n(e);new MutationObserver(e=>{for(const t of e)if("childList"===t.type)for(const e of t.addedNodes)"LINK"===e.tagName&&"modulepreload"===e.rel&&n(e)}).observe(document,{childList:!0,subtree:!0})}function n(e){if(e.ep)return;e.ep=!0;const n=function(e){const n={};return e.integrity&&(n.integrity=e.integrity),e.referrerPolicy&&(n.referrerPolicy=e.referrerPolicy),"use-credentials"===e.crossOrigin?n.credentials="include":"anonymous"===e.crossOrigin?n.credentials="omit":n.credentials="same-origin",n}(e);fetch(e.href,n)}}();const e={category:"상품 구조",terms:[{id:"term-101",name:"만기일시지급식",aliases:["만기일시지급","만기일시지급형"],description:"예금 기간이 끝나는 날(만기)에 원금과 이자를 한 번에 받는 방식이에요.",example:"100만원을 1년 만기일시지급식 예금:\n- 1년 동안: 이자를 받지 않음\n- 만기일: 원금 100만원 + 이자 3만원 = 103만원을 한 번에 받음",importance:"이자를 중간에 받지 않으므로 복리 효과가 가장 큽니다. 당장 돈이 필요하지 않다면 가장 유리한 방식입니다.",relatedTerms:["월지급식","복리","만기"]},{id:"term-102",name:"월지급식",aliases:["월지급","월지급형","월이자지급식"],description:"매달 이자를 받는 방식이에요. 원금은 만기에 받고, 이자만 매달 통장에 들어옵니다.",example:"100만원을 연 3% 월지급식 1년 예금:\n- 매달: 약 2,500원의 이자 받음\n- 만기 시: 원금 100만원 + 마지막 달 이자\n\n총 12번에 걸쳐 이자를 나눠서 받습니다.",importance:"매달 생활비가 필요한 분들(은퇴자 등)에게 적합합니다. 단, 복리 효과가 없어서 만기일시지급보다 총 수익은 적습니다.",relatedTerms:["만기일시지급식","단리"]},{id:"term-103",name:"정기예금",aliases:["정기 예금"],description:"일정 기간 동안 돈을 맡기고 이자를 받는 가장 기본적인 예금 상품이에요. 목돈을 한 번에 맡기는 방식입니다.",example:"500만원을 1년 정기예금에 가입:\n- 처음: 500만원 한 번에 입금\n- 중간: 추가 입금 불가\n- 만기: 원금 + 이자를 받음",importance:"목돈이 있을 때 안전하게 이자를 받는 가장 기본적인 방법입니다.",relatedTerms:["정기적금","자유적립식","만기"]},{id:"term-104",name:"정기적금",aliases:["정기 적금"],description:"매달 일정 금액을 꾸준히 넣어서 저축하는 상품이에요. 월급처럼 규칙적으로 돈을 모을 수 있습니다.",example:"매달 50만원씩 1년 정기적금:\n- 1개월차: 50만원 입금\n- 2개월차: 50만원 입금\n- ...\n- 12개월차: 50만원 입금\n- 만기: 원금 600만원 + 이자",importance:"목돈이 없어도 매달 조금씩 저축할 수 있어서 월급쟁이에게 적합합니다.",relatedTerms:["정기예금","자유적립식","정액적립식"]},{id:"term-105",name:"자유적립식",aliases:["자유적립","자유적립형"],description:"원할 때 원하는 만큼 돈을 넣을 수 있는 적금이에요. 매달 금액을 정하지 않아도 됩니다.",example:"자유적립식 적금:\n- 1월: 30만원 입금\n- 2월: 50만원 입금\n- 3월: 입금 안 함\n- 4월: 70만원 입금\n\n수입이 불규칙해도 자유롭게 저축 가능",importance:"프리랜서나 수입이 불규칙한 분들에게 적합합니다. 여유가 있을 때 많이 넣고, 어려울 때는 안 넣어도 됩니다.",relatedTerms:["정기적금","정액적립식"]},{id:"term-106",name:"정액적립식",aliases:["정액적립","정액 적립"],description:"매달 정해진 금액을 꼭 넣어야 하는 적금이에요. 약속한 금액을 매달 빠짐없이 입금해야 합니다.",example:"매달 50만원 정액적립식:\n- 매달 정확히 50만원 입금 필수\n- 못 넣으면 약정 위반\n- 적게 넣거나 안 넣으면 불이익\n\n일반 정기적금이 대부분 정액적립식입니다.",importance:"매달 일정한 수입이 있는 직장인에게 적합하지만, 수입이 불규칙하면 어려울 수 있습니다.",relatedTerms:["자유적립식","정기적금"]},{id:"term-107",name:"중도해지",aliases:["중도 해지"],description:"예금이나 적금의 약속 기간이 끝나기 전에 미리 해지하는 것이에요. 급하게 돈이 필요할 때 찾을 수 있지만, 불이익이 있습니다.",example:"1년 만기 연 3% 예금에 100만원, 6개월 만에 해지:\n- 원래 받을 이자: 약 3만원\n- 중도해지 이자 (1% 적용): 약 5,000원\n- 손해: 약 2만 5,000원",importance:"중도해지하면 이자를 거의 못 받습니다. 예금 가입 전에 중간에 돈을 꺼낼 일이 없는지 신중하게 생각하세요.",relatedTerms:["만기","중도해지이율","약정이율"]},{id:"term-108",name:"만기",aliases:["만기일","만기 시점"],description:"예금이나 적금 계약 기간이 끝나는 시점이에요. 약속한 기간을 다 채운 날입니다.",example:"2024년 1월 1일에 1년 만기 예금 가입:\n- 만기일: 2025년 1월 1일\n- 이날 원금과 이자를 모두 받을 수 있음",importance:"만기일에 찾아야 약속한 이자를 다 받습니다. 만기 전에 찾으면(중도해지) 이자가 적고, 만기 후 방치하면 금리가 낮아질 수 있습니다.",relatedTerms:["중도해지","만기일시지급식","자동연장"]},{id:"term-109",name:"자동연장",aliases:["자동 연장","재예치"],description:"만기가 되었을 때 찾아가지 않으면 자동으로 같은 조건으로 다시 예금을 시작하는 것이에요.",example:"1년 만기 예금 자동연장 설정:\n- 만기일에 찾지 않으면\n- 원금 + 이자를 합쳐서\n- 자동으로 1년 더 예금 시작\n\n(단, 금리는 재가입 시점의 금리 적용)",importance:"만기를 깜빡하고 놓쳐도 원금이 사라지지 않습니다. 하지만 금리가 낮아질 수 있으니 확인이 필요합니다.",relatedTerms:["만기","자동해지"]},{id:"term-110",name:"자동해지",aliases:["자동 해지"],description:"만기가 되면 자동으로 예금을 해지하고 원금과 이자를 입출금 통장으로 옮기는 것이에요.",example:"1년 만기 예금 자동해지 설정:\n- 만기일 되면\n- 자동으로 해지\n- 연결된 입출금 통장에 원금 + 이자 입금",importance:"만기 후 곧바로 돈이 필요한 경우 편리합니다. 하지만 다시 예금하려면 새로 가입해야 합니다.",relatedTerms:["만기","자동연장"]}]},n={category:"상품 구조",terms:[{id:"term-201",name:"거치식",aliases:["거치형","거치"],description:"목돈을 한 번에 넣고 일정 기간 동안 그대로 두는 방식이에요. 중간에 돈을 추가하거나 빼지 않습니다.",example:"500만원 거치식 예금:\n- 처음: 500만원 한 번에 입금\n- 기간 중: 아무것도 안 함\n- 만기: 원금 + 이자 받음\n\n정기예금이 대표적인 거치식입니다.",importance:"목돈이 있을 때 사용하는 방식입니다. 적립식보다 처음 금액이 크므로 이자도 많이 받습니다.",relatedTerms:["적립식","정기예금"]},{id:"term-202",name:"적립식",aliases:["적립형"],description:"매달 일정 금액을 꾸준히 넣어서 모으는 방식이에요. 조금씩 저축하는 것입니다.",example:"매달 50만원 적립식:\n- 1개월: 50만원 입금\n- 2개월: 50만원 더 입금 (누적 100만원)\n- 3개월: 50만원 더 입금 (누적 150만원)\n\n정기적금이 대표적인 적립식입니다.",importance:"목돈이 없어도 매달 조금씩 모을 수 있어서 월급쟁이에게 적합합니다.",relatedTerms:["거치식","정기적금","자유적립식"]},{id:"term-203",name:"파킹통장",aliases:["파킹 통장","파킹계좌"],description:"잠깐 주차하듯이 돈을 넣어두는 통장이에요. 자유롭게 입출금하면서도 이자를 받을 수 있는 상품입니다.",example:"파킹통장에 100만원:\n- 오늘: 100만원 입금\n- 3일 후: 50만원 출금\n- 1주일 후: 30만원 입금\n\n언제든 자유롭게 입출금하면서 일 단위로 이자 계산",importance:"급하게 쓸 일이 생길 수 있는 비상금을 보관하기 좋습니다. 정기예금보다 금리는 낮지만 자유롭습니다.",relatedTerms:["입출금자유예금","CMA","MMDA"]},{id:"term-204",name:"입출금자유예금",aliases:["입출금 자유 예금","자유예금"],description:"언제든지 돈을 넣고 뺄 수 있는 예금이에요. 제한 없이 자유롭게 사용할 수 있지만 이자는 거의 없습니다.",example:"은행의 기본 통장:\n- 원할 때 입금\n- 원할 때 출금\n- 이자는 연 0.1% 정도로 매우 낮음",importance:"생활비 통장으로 사용하는 일반적인 예금입니다. 저축보다는 거래 용도입니다.",relatedTerms:["파킹통장","보통예금"]},{id:"term-205",name:"보통예금",aliases:["보통 예금"],description:"가장 기본적인 입출금 통장이에요. 은행에서 처음 만드는 통장이 보통 보통예금입니다.",example:"은행에서 통장 만들 때:\n'보통예금 계좌 개설하시겠습니까?'\n\n급여 받고, 생활비 쓰는 기본 통장",importance:"거래의 기본이 되는 통장입니다. 저축용이 아니라 사용 용도입니다.",relatedTerms:["입출금자유예금","저축예금"]},{id:"term-206",name:"저축예금",aliases:["저축 예금"],description:"자유롭게 입출금하면서 보통예금보다 조금 높은 이자를 받는 예금이에요. 파킹통장과 비슷합니다.",example:"저축예금 vs 보통예금:\n- 보통예금: 연 0.1% 이자\n- 저축예금: 연 1~2% 이자\n\n둘 다 자유롭게 입출금 가능하지만 저축예금이 이자가 더 높음",importance:"당장 쓰지 않을 돈을 보통예금에 놔두는 것보다는 저축예금에 넣어두면 이자를 더 받습니다.",relatedTerms:["보통예금","파킹통장"]},{id:"term-207",name:"CMA",aliases:["씨엠에이","종합자산관리계좌"],description:"증권사에서 파는 파킹통장 같은 상품이에요. 자유롭게 입출금하면서 은행보다 높은 이자를 받을 수 있습니다.",example:"CMA 계좌:\n- 증권사 앱에서 개설\n- 자유롭게 입출금\n- 은행 파킹통장보다 금리 조금 높음\n- 예금자보호 적용 (금융사에 따라 다름)",importance:"은행 파킹통장의 대안입니다. 금리가 조금 더 높지만 증권사 앱을 써야 합니다.",relatedTerms:["MMDA","파킹통장","RP"]},{id:"term-208",name:"MMDA",aliases:["엠엠디에이","시장금리부예금"],description:"시장 금리를 따라가는 예금 상품이에요. 자유롭게 입출금하면서 시장 금리에 연동된 이자를 받습니다.",example:"MMDA:\n- 자유 입출금 가능\n- 시장 금리에 따라 이자율 변동\n- 금리 오르면 MMDA 이자도 오름\n- 예금자보호 적용",importance:"금리가 오르는 시기에 유리합니다. CMA와 비슷하지만 은행 상품이라 익숙합니다.",relatedTerms:["CMA","파킹통장"]},{id:"term-209",name:"RP",aliases:["알피","환매조건부채권"],description:"증권사에서 파는 단기 투자 상품이에요. 보통 하루짜리로 매일 자동으로 재투자되어 파킹통장처럼 사용됩니다.",example:"RP 계좌 (CMA의 일종):\n- 하루 단위로 투자\n- 매일 자동 재투자\n- 자유 입출금 가능\n- 단기 금리로 이자 지급",importance:"CMA 통장에서 돈을 RP에 투자하여 이자를 받는 방식입니다. 실질적으로는 파킹통장처럼 사용됩니다.",relatedTerms:["CMA","MMDA"]}]},t={category:"예금 보호",terms:[{id:"term-401",name:"예금자보호법",aliases:["예금자 보호법","예보법"],description:"은행이 망해도 고객의 예금을 보호해주는 법이에요. 1인당 5천만원까지는 국가가 보장합니다.",example:"은행이 파산한다면:\n- 1인당 5천만원까지: 예금보험공사가 100% 지급\n- 5천만원 초과: 받지 못할 수 있음\n\n여러 은행에 나눠서 예금하면 각각 5천만원씩 보호",importance:"아무리 큰 은행도 망할 수 있습니다. 5천만원 이상은 여러 은행에 나눠서 예금하는 것이 안전합니다.",relatedTerms:["예금보험공사","보호한도","원금"]},{id:"term-402",name:"예금보험공사",aliases:["예보","예금보험"],description:"은행이 망했을 때 고객의 예금을 대신 갚아주는 국가 기관이에요. 줄여서 '예보'라고 부릅니다.",example:"예금보험공사의 역할:\n- 평소: 은행들에게 보험료 받음\n- 은행 파산 시: 고객에게 최대 5천만원 지급\n\n마치 자동차 보험처럼 은행의 보험",importance:"예금보험공사가 있어서 5천만원까지는 안심하고 예금할 수 있습니다.",relatedTerms:["예금자보호법","보호한도"]},{id:"term-403",name:"보호한도",aliases:["보호 한도","예금보호한도"],description:"예금자보호법으로 보호받을 수 있는 최대 금액이에요. 현재는 1인당 1개 은행에서 5천만원까지입니다.",example:"A은행에 7천만원 예금:\n- 보호 금액: 5천만원 (원금 + 이자 합산)\n- 미보호: 2천만원 (은행 파산 시 못 받을 수 있음)\n\n여러 은행 사용:\n- A은행 5천만원: 전액 보호\n- B은행 3천만원: 전액 보호\n- 총 8천만원 모두 보호",importance:"5천만원 이상의 목돈은 꼭 여러 은행에 나눠서 예금하세요. 하나의 은행에 몰아두면 위험합니다.",relatedTerms:["예금자보호법","원금"]},{id:"term-404",name:"원금",aliases:["원금액","원래 금액"],description:"처음에 넣은 돈의 금액이에요. 이자를 제외한 순수하게 내가 입금한 돈입니다.",example:"100만원 예금:\n- 원금: 100만원 (내가 넣은 돈)\n- 이자: 3만원 (은행이 주는 돈)\n- 만기 수령액: 103만원\n\n원금은 보장되지만 이자는 상황에 따라 변할 수 있음",importance:"예금자보호 한도 5천만원은 원금과 이자를 합친 금액입니다. 원금만 5천만원이 아닙니다.",relatedTerms:["이자","예금자보호법"]},{id:"term-405",name:"이자",aliases:["이자금액"],description:"은행에 돈을 맡긴 대가로 받는 돈이에요. 원금에 금리를 곱해서 계산합니다.",example:"100만원을 연 3% 1년 예금:\n- 이자 계산: 100만원 × 3% = 3만원\n- 세후 이자: 약 25,380원 (세금 15.4% 제외)\n\n실제 통장에 들어오는 이자는 세후 금액",importance:"이자가 수익입니다. 금리가 높을수록, 원금이 클수록, 기간이 길수록 이자가 많아집니다.",relatedTerms:["원금","연이율","이자소득세"]}]},a={category:"예금 보호",terms:[{id:"term-501",name:"1인당 5천만원",aliases:["5천만원 한도","오천만원"],description:"예금자보호법으로 보호받을 수 있는 금액이에요. 한 은행에 1명당 최대 5천만원까지 보호됩니다.",example:"A은행에 예금:\n- 본인 명의: 6천만원 → 5천만원만 보호\n- 배우자 명의: 3천만원 → 전액 보호\n\n같은 은행이어도 명의가 다르면 각각 5천만원씩 보호",importance:"가족이 많으면 여러 명의로 나눠서 예금하면 더 많은 금액을 보호받을 수 있습니다.",relatedTerms:["예금자보호법","보호한도"]}]},r={category:"특수 상품",terms:[{id:"term-601",name:"요구불예금",aliases:["요구불 예금"],description:"언제든지 요구하면 바로 돌려받을 수 있는 예금이에요. 입출금이 자유로운 통장입니다.",example:"보통예금 = 요구불예금\n- 오늘 넣고 내일 찾아도 됨\n- 제한 없이 자유롭게 사용\n- 이자는 매우 낮음 (연 0.1% 정도)",importance:"생활비나 비상금처럼 언제든 써야 할 돈은 요구불예금에 넣어둬야 합니다.",relatedTerms:["정기예금","보통예금"]},{id:"term-602",name:"CD",aliases:["씨디","양도성예금증서"],description:"증서 형태로 발행되는 예금이에요. 다른 사람에게 팔 수 있다는 특징이 있지만, 일반 고객은 거의 사용하지 않습니다.",example:"CD는 주로 기업이나 기관투자가가 사용:\n- 고액 단기 예금\n- 증서 형태로 발행\n- 만기 전 다른 사람에게 매도 가능\n\n개인은 정기예금을 더 많이 사용",importance:"일반 개인 고객은 잘 사용하지 않는 상품입니다. 정기예금과 비슷하지만 더 전문적입니다.",relatedTerms:["정기예금","RP"]}]};function i(e){const n=e.category||"금융 용어";return e.terms.map(e=>({...e,category:n}))}const s={isEnabled:!0,selectionMethod:"both",popupPosition:"auto",popupSize:"medium",hoverPreviewEnabled:!1,allowAnalytics:!1};function m(){return[...i(e),...i(n),...i(t),...i(a),...i(r)].length}const o=document.getElementById("enableToggle"),c=document.getElementById("statusText"),l=document.getElementById("termCount");async function d(){const e=o.checked;await async function(e,n){try{return await chrome.storage.sync.set({[e]:n}),!0}catch(t){return console.error(`Failed to save setting ${e}:`,t),!1}}("isEnabled",e),p(e);(await chrome.tabs.query({})).forEach(n=>{chrome.tabs.sendMessage(n.id,{action:"toggleExtension",enabled:e}).catch(()=>{})})}function p(e){c.textContent=e?"활성":"비활성",c.className="status-text "+(e?"active":"inactive")}!async function(){const e=await async function(){try{return await chrome.storage.sync.get(s)}catch(e){return console.error("Failed to get settings:",e),s}}();o.checked=e.isEnabled,p(e.isEnabled),function(){try{const e=m();l.textContent=`${e}개`}catch(e){console.error("Failed to load stats:",e)}}(),o.addEventListener("change",d)}();
